preConditionHook:
// THE PULLBACK NOW UNDERWAY IS AT LEAST growthMultiple TIMES AS DEEP AS THE
// LARGEST PULLBACK SEEN EARLIER IN THIS TREND. On a small-pullback trend day
// Brooks expects exactly this later in the session and warns against reading
// it as a reversal, so the rule is most useful NEGATED, as "this pullback is
// still within the trend's normal size". Brooks gives "about twice the size";
// growthMultiple defaults to 1.5 as the conservative reading, with 2.0 the
// book's own number. His 11:00 a.m. gate is the catalog's TimeWindow in a
// separate pane, not part of this rule.
//
// KEPT APART FROM MaxPullbackDepthBelowThreshold: that rule caps the
// HISTORICAL MAXIMUM against an external threshold, this one compares the
// LIVE pullback against that maximum, and the two fire on different bars.
// What is new here is holding the two apart -- the running depth of the
// pullback in progress and the largest COMPLETED one before it.
//
// A PULLBACK COMPLETES WHEN A NEW EXTREME IS MADE. On a bar that takes out
// the running high the pullback just ended is folded into priorPbUp and the
// live depth is cleared; on every other bar the live depth is extended. That
// is the whole segmentation, and it needs no pivot search.
//
// THE LEG RESET IS THE ALWAYS-IN FLIP, the standing corpus decision, inlined
// here as TrendDurationBars inlines it and with the same inputs so every
// consumer reads the same state: the direction FLIPS on consecutiveBars
// consecutive STRONG TREND BARS -- body at least bodyFraction of the bar's
// own range and BOTH tails no more than tailFraction of it -- holds until the
// opposite flip, and is UNDEFINED (aiDir = 0) until the first flip ever. The
// flip bar seeds the extremes and is skipped by the tracker, so its own range
// is never counted as the leg's first pullback.
//
// priorPbUp > 0 is load-bearing: with no completed pullback yet the test
// would be depth >= 0, true on every bar. Compared, never divided.
//
// Mirrored: the long side reads the bull leg's give-back below its running
// high, the short side the bear leg's give-back above its running low.
//
// Deepest bar touched: consecutiveBars - 1.
allBull = true;
allBear = true;
for (kk = 0; kk < (int)consecutiveBars; ++kk) {
    rng = high[kk] - low[kk];
    if (el_le(close[kk], open[kk])) allBull = false;
    if (el_lt(close[kk] - open[kk], bodyFraction * rng)) allBull = false;
    if (el_gt(high[kk] - close[kk], tailFraction * rng)) allBull = false;
    if (el_gt(open[kk] - low[kk], tailFraction * rng)) allBull = false;
    if (el_ge(close[kk], open[kk])) allBear = false;
    if (el_lt(open[kk] - close[kk], bodyFraction * rng)) allBear = false;
    if (el_gt(close[kk] - low[kk], tailFraction * rng)) allBear = false;
    if (el_gt(high[kk] - open[kk], tailFraction * rng)) allBear = false;
}
flipped = false;
if (allBull && aiDir != 1) {
    aiDir = 1;
    flipped = true;
}
if (allBear && aiDir != -1 && flipped == false) {
    aiDir = -1;
    flipped = true;
}
if (flipped) {
    runHigh = high[0];
    runLow = low[0];
    curPbUp = 0.0;
    priorPbUp = 0.0;
    curPbDn = 0.0;
    priorPbDn = 0.0;
}
if (flipped == false) {
    if (el_gt(high[0], runHigh)) {
        if (el_gt(curPbUp, priorPbUp)) priorPbUp = curPbUp;
        curPbUp = 0.0;
        runHigh = high[0];
    } else {
        if (el_gt(runHigh - low[0], curPbUp)) curPbUp = runHigh - low[0];
    }
    if (el_lt(low[0], runLow)) {
        if (el_gt(curPbDn, priorPbDn)) priorPbDn = curPbDn;
        curPbDn = 0.0;
        runLow = low[0];
    } else {
        if (el_gt(high[0] - runLow, curPbDn)) curPbDn = high[0] - runLow;
    }
}
growUp = (aiDir == 1) && el_gt(priorPbUp, 0.0) && el_ge(curPbUp, growthMultiple * priorPbUp);
growDn = (aiDir == -1) && el_gt(priorPbDn, 0.0) && el_ge(curPbDn, growthMultiple * priorPbDn);
